{"security_risk": "LOW", "summary": "Print checkbox appearance state names for proper values", "command": "python3 - <<'PY'
from pypdf import PdfReader
r=PdfReader('/root/sc100-blank.pdf')
want=set(['Checkbox50[0]','Checkbox50[1]','Checkbox60[0]','Checkbox60[1]','Checkbox61[0]','Checkbox61[1]','Checkbox62[0]','Checkbox62[1]','Checkbox63[0]','Checkbox63[1]','Checkbox1[0]','Checkbox2[0]','Checkbox3[0]','Checkbox4[0]','Checkbox5[0]'])
for pi,page in enumerate(r.pages):
    annots=page.get('/Annots')
    if not annots:
        continue
    for a in annots:
        obj=a.get_object()
        t=obj.get('/T')
        if not t:
            continue
        if t in want:
            ap=obj.get('/AP')
            n=None
            if ap:
                n=ap.get('/N')
            states=[]
            if isinstance(n,dict):
                states=list(n.keys())
            print(f'page {pi+1} {t}: V={obj.get("/V")} AS={obj.get("/AS")} states={states}')
PY"}

